538			{"tab in name is json escaped", "{\"a\\tb\":7}", `context["a\tb"]`},
539			{"quote in name is json escaped", `{"a\"b":7}`, `context["a\"b"]`},
540			{"backslash in name is json escaped", `{"a\\b":7}`, `context["a\\b"]`},
541			{"brackets are not array indices", `{"names[0]":7}`, `context["names[0]"]`},
542			{"leading digit is bracketed", `{"0ab":7}`, `context["0ab"]`},
543			{"dash is bracketed", `{"a-b":7}`, `context["a-b"]`},
