311	func TestCLIEvaluateOutOfRangeNumbersRejected(t *testing.T) {
312		hugeInt := "1" + strings.Repeat("0", 400)
313		cases := []struct {
314			name    string
315			key     string
316			context string
317			want    string // stderr 必须包含的片段
318		}{
319			{"exponent overflow", "feature-big", `{"plan":1e400}`, "context.plan"},
320			{"negative exponent overflow", "feature-big", `{"plan":-1e400}`, "context.plan"},
321			{"400-digit integer", "feature-big", `{"plan":` + hugeInt + `}`, "context.plan"},
322			{"object value holding big number", "feature-big", `{"plan":{"inner":1e400}}`, "context.plan"},
323			{"array value holding big number", "feature-big", `{"plan":[1e400]}`, "context.plan"},
324			{"attr not referenced by any rule", "feature-plain", `{"unreferenced":1e400}`, "context.unreferenced"},
325			{"disabled flag does not bypass validation", "feature-off", `{"plan":1e400}`, "context.plan"},
326			{"bool before big number reports first attr", "feature-big", `{"zeta":false,"plan":1e400}`, "context.zeta"},
327		}
328		for _, tc := range cases {
329			t.Run(tc.name, func(t *testing.T) {
330				h := newHarness(t, bigNumberConfig, tc.context)
331				var stdout, stderr bytes.Buffer
332				code := run(h.evalArgs(tc.key), &stdout, &stderr)
333				if code == 0 {
334					t.Fatalf("expected non-zero exit")
335				}
336				if stdout.Len() != 0 {
337					t.Fatalf("stdout must be empty on validation failure: %q", stdout.String())
338				}
339				msg := stderr.String()
340				if !strings.Contains(msg, tc.want) || !strings.Contains(msg, "value must be a string") {
341					t.Fatalf("stderr=%q, want %s string-type error", msg, tc.want)
342				}
343				if strings.Contains(msg, "invalid JSON") {
344					t.Fatalf("a legal big number must be a type error, not a JSON syntax error: %q", msg)
345				}
346			})
